const input = $input.first().json;
const body = input.body ?? input;
const customers = Array.isArray(body.customers) ? body.customers : [];
const campaignId = String(body.campaign_id || `campaign-${Date.now()}`);
const templateName = String(body.template_name || '').trim();
const language = String(body.language || 'es').trim();
const clean = (v) => String(v ?? '').replace(/[\u0000-\u001F\u007F]/g, ' ').replace(/\s+/g, ' ').trim();
const money = (v) => { const s = String(v ?? '').replace(/RD\$/gi, '').replace(/\$/g, '').replace(/,/g, '').trim(); const n = Number(s); return Number.isFinite(n) ? Math.round(n * 100) / 100 : NaN; };
const phone = (v) => { let d = String(v ?? '').replace(/\D/g, ''); if (d.startsWith('00')) d = d.slice(2); if (d.length === 10) d = `1${d}`; return /^\d{11,15}$/.test(d) ? d : ''; };
const yes = (v) => ['si','sí','yes','true','1','autorizado'].includes(clean(v).toLowerCase());
const noContact = (v) => yes(v);
const normalized = customers.map((raw, row) => {
  const firstName = clean(raw.first_name ?? raw.nombre);
  const lastName = clean(raw.last_name ?? raw.apellido);
  const fullName = clean(`${firstName} ${lastName}`) || 'Cliente';
  const balance = money(raw.balance ?? raw.saldo ?? raw.monto);
  const normalizedPhone = phone(raw.phone ?? raw.telefono ?? raw.celular);
  const status = clean(raw.status ?? raw.estatus ?? raw.estado).toLowerCase();
  const contract = clean(raw.contract ?? raw.contrato ?? raw.referencia);
  const clientId = clean(raw.id ?? raw.cliente_id);
  let eligible = true; let reason = 'OK';
  if (!contract && !clientId) { eligible = false; reason = 'MISSING_ID'; }
  else if (!normalizedPhone) { eligible = false; reason = 'INVALID_PHONE'; }
  else if (!Number.isFinite(balance) || balance <= 0) { eligible = false; reason = 'INVALID_OR_ZERO_BALANCE'; }
  else if (!yes(raw.whatsapp_consent ?? raw.consentimiento_whatsapp ?? raw.consentimiento)) { eligible = false; reason = 'NO_CONSENT'; }
  else if (noContact(raw.do_not_contact ?? raw.no_contactar ?? raw.excluir)) { eligible = false; reason = 'DO_NOT_CONTACT'; }
  else if (status.includes('legal')) { eligible = false; reason = 'LEGAL_BLOCKED'; }
  return { campaign_id: campaignId, row: row + 1, client_id: clientId, contract, first_name: firstName || 'Cliente', full_name: fullName, phone: normalizedPhone, balance, balance_text: `RD$${balance.toLocaleString('en-US', {minimumFractionDigits: 2, maximumFractionDigits: 2})}`, status, template_name: templateName, language, eligible, reason };
});
const counts = new Map();
for (const c of normalized) if (c.phone) counts.set(c.phone, (counts.get(c.phone) || 0) + 1);
for (const c of normalized) if (c.eligible && counts.get(c.phone) > 1) { c.eligible = false; c.reason = 'DUPLICATE_PHONE_IN_CAMPAIGN'; }
if (!normalized.length) return [{ json: { campaign_id: campaignId, eligible: false, reason: 'EMPTY_CAMPAIGN', row: 0 } }];
return normalized.map((json) => ({ json }));

const response = $input.first().json;
let customer = {};
try { customer = $('Lote individual').item.json; } catch {}
const statusCode = Number(response.statusCode ?? response.status ?? 0);
const body = response.body ?? response;
const messageId = body?.messages?.[0]?.id ?? '';
const ok = statusCode >= 200 && statusCode < 300 && Boolean(messageId);
const error = body?.error?.message ?? response.error?.message ?? (ok ? '' : `Respuesta no aceptada (HTTP ${statusCode || 'desconocido'})`);
return [{ json: { ...customer, outcome: ok ? 'ACCEPTED' : 'FAILED_CONTINUED', http_status: statusCode, message_id: messageId, error, processed_at: new Date().toISOString() } }];
